// === ZENTRALE CONFIG ===
// Positions-Typen aus JTL, die NICHT nach Shopify uebernommen werden sollen.
// Abgleich erfolgt spaeter case-insensitive gegen den JTL-Positionstyp bzw. Titel.
const SKIP_TYPES = ['versand', 'karton', 'verpackung', 'rabatt', 'gutschein'];

// SKUs, die generell ignoriert werden sollen (optional pflegen)
const SKIP_SKUS = [];

const staticData = $getWorkflowStaticData('global');
staticData.config = { SKIP_TYPES, SKIP_SKUS };

// CSV-Binary unveraendert durchreichen
return $input.all();

// Erwartet eine Spalte mit der Auftragsnummer.
// Akzeptiert 'Name', 'Auftragsnr', 'Auftragsnummer' oder 'orderName'.
const items = $input.all().map(i => i.json);

const seen = new Set();
const orders = [];

for (const row of items) {
  const raw = String(
    row['Name'] ?? row['Auftragsnr'] ?? row['Auftragsnummer'] ?? row['orderName'] ?? ''
  ).trim();
  if (!raw) continue;
  if (seen.has(raw)) continue;
  seen.add(raw);
  orders.push({ auftragsNr: raw });
}

return orders.map(o => ({ json: o }));

// toAdd einmalig leeren, Token durchreichen, alle Auftragsnummern weitergeben.
const staticData = $getWorkflowStaticData('global');
staticData.toAdd = [];

const token = $json.access_token;
const orders = $('Auftragsnummern extrahieren (dedupe)').all().map(i => i.json);

return orders.map(o => ({
  json: { ...o, accessToken: token }
}));

// Rohe JTL-Positionen filtern: unerwuenschte Typen/SKUs raus.
// Ergebnis wird pro Auftrag in staticData.toAdd gesammelt (SKU noch nicht aufgeloest).
const staticData = $getWorkflowStaticData('global');
const cfg = staticData.config || { SKIP_TYPES: [], SKIP_SKUS: [] };
if (!Array.isArray(staticData.toAdd)) staticData.toAdd = [];

const auftragsNr = $('Loop je Auftrag (Sammeln)').item.json.auftragsNr;
const rows = $input.all().map(i => i.json);

const skipTypes = (cfg.SKIP_TYPES || []).map(s => String(s).toLowerCase());
const skipSkus  = (cfg.SKIP_SKUS  || []).map(s => String(s).toLowerCase());

const positionen = [];
for (const r of rows) {
  const sku   = String(r.sku || '').trim();
  const titel = String(r.titel || '').trim();
  const typ   = String(r.positionstyp || '').toLowerCase();
  const titelLc = titel.toLowerCase();

  // Typ-Filter: gegen positionstyp UND Titel pruefen
  const isSkipType = skipTypes.some(t => typ.includes(t) || titelLc.includes(t));
  if (isSkipType) continue;

  // SKU-Filter
  if (sku && skipSkus.includes(sku.toLowerCase())) continue;

  // Ohne SKU kann keine echte Variante aufgeloest werden -> markieren, spaeter sichtbar
  positionen.push({
    sku,
    titel,
    menge: Number(r.menge) || 1,
    einzelpreis: r.einzelpreis
  });
}

if (positionen.length > 0) {
  staticData.toAdd.push({ auftragsNr, positionen });
}

return [{ json: { auftragsNr, gefiltertePositionen: positionen.length, gesammelt: staticData.toAdd.length } }];

// Loest je gesammelter Position die Shopify-Variante ueber SKU auf
// und erzeugt EIN Item pro zu ergaenzender Position.
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toAdd || [];

const out = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    out.push({
      json: {
        auftragsNr: order.auftragsNr,
        sku: pos.sku,
        titel: pos.titel,
        menge: pos.menge,
        einzelpreis: pos.einzelpreis
      }
    });
  }
}

if (!out.length) {
  return [{ json: { WARNUNG: 'toAdd ist leer \u2013 keine Positionen zu ergaenzen' } }];
}

return out;

// SKU -> ProductVariant-GID + Order-GID aufloesen.
// 1) Variante ueber SKU per GraphQL productVariants(query:"sku:...") suchen
// 2) Order-GID ueber Auftragsnummer (Shopify order name) suchen
const item = $input.item.json;
const sku = String(item.sku || '').trim();
const auftragsNr = String(item.auftragsNr || '').trim();

// Shopify-Order-Name benoetigt fuehrendes '#', falls nicht vorhanden
const orderName = auftragsNr.startsWith('#') ? auftragsNr : `#${auftragsNr}`;

const body = {
  query: `query resolve($skuQuery: String!, $orderQuery: String!) {
    productVariants(first: 1, query: $skuQuery) {
      edges { node { id sku title } }
    }
    orders(first: 1, query: $orderQuery) {
      edges { node { id name } }
    }
  }`,
  variables: {
    skuQuery: `sku:${sku}`,
    orderQuery: `name:${orderName}`
  }
};

return {
  json: {
    ...item,
    orderName,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.first().json;
const variantEdge = resp?.data?.productVariants?.edges?.[0]?.node || null;
const orderEdge   = resp?.data?.orders?.edges?.[0]?.node || null;

const src = $('Query bauen (SKU + Order aufloesen)').item.json;

if (!variantEdge) {
  throw new Error(`Keine Variante fuer SKU '${src.sku}' gefunden (Auftrag ${src.auftragsNr})`);
}
if (!orderEdge) {
  throw new Error(`Keine Bestellung fuer '${src.orderName}' gefunden`);
}

return {
  json: {
    auftragsNr: src.auftragsNr,
    orderName: src.orderName,
    sku: src.sku,
    menge: src.menge,
    variantId: variantEdge.id,
    orderGid: orderEdge.id,
    accessToken: src.accessToken
  }
};

const item = $input.item.json;

const body = {
  query: `mutation orderEditBegin($id: ID!) { orderEditBegin(id: $id) { calculatedOrder { id } userErrors { field message } } }`,
  variables: { id: item.orderGid }
};

return {
  json: {
    ...item,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
}
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) {
  throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));
}

const src = $('Aufloesung pruefen').item.json;

return {
  json: {
    ...src,
    calcOrderId
  }
};

const item = $input.item.json;

const body = {
  query: `mutation orderEditAddVariant($id: ID!, $variantId: ID!, $quantity: Int!, $allowDuplicates: Boolean) {
    orderEditAddVariant(id: $id, variantId: $variantId, quantity: $quantity, allowDuplicates: $allowDuplicates) {
      calculatedLineItem {
        id
        title
        sku
        variantTitle
        discountedUnitPriceSet { shopMoney { amount currencyCode } }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    variantId: item.variantId,
    quantity: Number(item.menge) || 1,
    allowDuplicates: true
  }
};

return {
  json: {
    ...item,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.first().json;
const add = resp?.data?.orderEditAddVariant;
const errs = add?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditAddVariant userErrors: ' + JSON.stringify(errs));
}

const src = $('CalcOrder auslesen').item.json;

return {
  json: {
    ...src,
    addedLineItem: add?.calculatedLineItem || null
  }
};

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));
}

return {
  json: {
    status: 'OK',
    orderName: $('Add-Ergebnis pruefen').item.json.orderName,
    committedOrder: commit?.order || null
  }
};
